local OverseaRenovaListCell = Class('OverseaRenovaListCell')
local CurryEnvPath = "Game.Behaviours.CommonCurrencyNode"
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
---@type MaidCoffeeComponent
local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
function OverseaRenovaListCell:__init()
    self.index = nil
    self.priceCallBack = nil
    self.callBack = nil
end

function OverseaRenovaListCell:__delete()
    self.index = nil
    self.priceCallBack = nil
    self.callBack = nil
end

function OverseaRenovaListCell:Awake()
    SetButtonAction(self.BtnNode.gameObject,Bind(self,self.OnBtnNodeClick))
    SetButtonAction(self.Price.gameObject,Bind(self,self.OnPriceClick))
    self:InitEnv()
end

function OverseaRenovaListCell:SetCallBack(callBack,priceCallBack,index)
    self.callBack = callBack
    self.priceCallBack = priceCallBack
    self.index = index
end

function OverseaRenovaListCell:InitEnv()
    if self.TextCurrentPrice then
        local env = CfUtils.GetLuaScr(self.TextCurrentPrice,CurryEnvPath)
        if env then
            self.curPriceEnv = env
        end
    end

    if self.TextOldPrice then
        local env = CfUtils.GetLuaScr(self.TextOldPrice,CurryEnvPath)
        if env then
            self.oldPriceEnv = env
        end
    end
end
---刷新套装显示
function OverseaRenovaListCell:RefreshSuitShow(data,furnitureId)
    self.isSuit = true
    self.data = data
    self:SetCommonShow()
    self:SetSelectStatus(false)
    local isHaveSuit = component:IsHaveCattySuit(self.data.furnitureIds)
    self:SetCommonPriceShow(isHaveSuit,true)
    local isUse = component:IsSuitInUse(self.data.furnitureIds)
    CfUtils.SetActive(self.Use,isUse)
    ---@type MaidCoffeeUtils
    local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
    local AestheticsValue = MaidCoffeeUtils.GetSuitAestheticsValue(self.data.furnitureIds)
    CfUtils.FillText(self.TextNumber,AestheticsValue)

    if data.refId == checkNumber(furnitureId) then
        self:OnBtnNodeClick()
    end
end

function OverseaRenovaListCell:RefreshIsHave()
    local isHave = false
    if self.isSuit then
        isHave = component:IsHaveCattySuit(self.data.furnitureIds)
    else
        isHave = component:IsHaveRenovated(self.data.furnitureId)
        self:SetRedGoStatus(false)
        if isHave then
            local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
            local isHaveRedPoint = maidCoffeeComponent:IsShowAvatarsNew(self.data.furnitureId)
            if isHaveRedPoint then
                self:SetRedGoStatus(true)
            end
        end
    end
    self:SetCommonPriceShow(isHave,self.isSuit)
end

function OverseaRenovaListCell:RefreshInUse()
    local isUse
    if self.isSuit then
        isUse = component:IsSuitInUse(self.data.furnitureIds)
    else
        isUse = component:IsRenovatedInUse(self.data.furnitureId)
    end
    CfUtils.SetActive(self.Use,isUse)
end

function OverseaRenovaListCell:SetCommonPriceShow(isHave,isSuit)
    self.isDirect = false
    if not isHave then
        if not isNull(self.data.isDirect) then
            if self.data.isDirect == 1 then
                KTool.SetActive(self.Price.gameObject,false)
                KTool.SetActive(self.DirectPrice.gameObject,true)
                self.isDirect = true

                local shopData = MaidCoffeeUtils.GetMallRenovateShopData(self.data.refId)
                --- 这个是因为直购里面 会有货币
                local isDirect = not isNull(shopData.prices) and (not next(shopData.prices))
                KTool.SetActive(self.CurGoodsIcon.gameObject,not isDirect)
                KTool.SetActive(self.OldGoodsIcon.gameObject,not isDirect)

                if isDirect then
                    CfUtils.FillText(self.OldDirectPrice, CfUtils.GetCustomDisplayPrice(shopData.original, nil, 24))
                    local windowPricesId = CfUtils.GetWindowsPriceId(shopData)
                    CfUtils.FillText(self.CurDirectPrice, CfUtils.GetCustomDisplayPrice(windowPricesId, shopData.channelProductId, 24))
                else
                    local goodId = shopData.prices.currency
                    CfUtils.FillText(self.OldDirectPrice, shopData.prices.original)
                    CfUtils.FillText(self.CurDirectPrice,shopData.prices.current)

                    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodId)
                    if not isNull(goodsVo) then
                        CfUtils.FillImage(self.CurGoodsIcon,goodsVo.photoPath)
                        CfUtils.FillImage(self.OldGoodsIcon,goodsVo.photoPath)
                    end
                end
            else
                KTool.SetActive(self.Price.gameObject,true)
                KTool.SetActive(self.DirectPrice.gameObject,false)
            end
        else
            KTool.SetActive(self.Price.gameObject,true)
            KTool.SetActive(self.DirectPrice.gameObject,false)
        end
    else
        KTool.SetActive(self.Price.gameObject,false)
        KTool.SetActive(self.DirectPrice.gameObject,false)
    end

    if not isHave then
        if isSuit and not self.isDirect then
            KTool.SetActive(self.TextOldPrice.gameObject,true)
            if self.data.type ~= 1 then
                self.curPriceEnv:SetCurrencyShow(self.data.goodsId,self.data.goodsNum)
                self.oldPriceEnv:SetCurrencyShow(self.data.goodsId,self.data.originalNum)
            else
                local curPrice,originPrice = component:GetRemainPrice(self.data.furnitureIds)
                self.curPriceEnv:SetCurrencyShow(self.data.goodsId,curPrice)
                self.oldPriceEnv:SetCurrencyShow(self.data.goodsId ,originPrice)
            end
        else
            self.curPriceEnv:SetCurrencyShow(self.data.goodsId,self.data.originalNum)
            KTool.SetActive(self.TextOldPrice.gameObject,false)
        end
    end
    CfUtils.SetActive(self.ImgLock,not isHave)
end

function OverseaRenovaListCell:SetCommonShow()
    CfUtils.FillText(self.TextName,self.data.name)
    CfUtils.SetActive(self.ImgHot,self.data.hot == 1)
    CfUtils.SetUISwitchImage(self.ImgQuality,self.data.quality)
    CfUtils.FillImage(self.ImgIcon,self.data.photoPath)
end
---和套装区分开来 刷新部件显示
function OverseaRenovaListCell:RefreshPartShow(data)
    self.data = data
    self.isSuit = false
    self:SetCommonShow()
    CfUtils.FillText(self.TextNumber,self.data.decorationValue)

    local isHave = component:IsHaveRenovated(self.data.furnitureId)
    self:SetCommonPriceShow(isHave,false)
    local isUse = component:IsRenovatedInUse(self.data.furnitureId)
    CfUtils.SetActive(self.Use,isUse)
    self:SetRedGoStatus(false)
    if isHave then
        local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local isHaveRedPoint = maidCoffeeComponent:IsShowAvatarsNew(self.data.furnitureId)
        if isHaveRedPoint then
            self:SetRedGoStatus(true)
        end
    end
end

function OverseaRenovaListCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

function OverseaRenovaListCell:SetRedGoStatus(status)
    KTool.SetActive(self.New.gameObject,status)
end

function OverseaRenovaListCell:OnBtnNodeClick()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local isHaveRedPoint = maidCoffeeComponent:IsShowAvatarsNew(self.data.furnitureId)
    if isHaveRedPoint then
        maidCoffeeComponent:RemoveRedPointId(self.data.furnitureId)
        self:SetRedGoStatus(false)
    end
    self:SetSelectStatus(true)
    if not isNull(self.callBack) then
        self.callBack(self)
    end
end

function OverseaRenovaListCell:OnPriceClick()
    if not isNull(self.priceCallBack) then
        self.priceCallBack(self.data)
    end
end

function OverseaRenovaListCell:SetSelectStatus(state)
    CfUtils.SetActive(self.StatusSelect.gameObject,state)
end

return OverseaRenovaListCell